using FinTrack.Shared.Kernel.Monetary;

namespace FinTrack.Budget.Contracts.V1.Buckets;

/// <summary>
/// Body of <c>POST /api/v1/buckets</c>. Answers 204. The client generates <paramref name="Id"/> (a
/// version 7 UUID); repeating the request with the same ID and the same values changes nothing,
/// with other values it fails with <c>bucket.id_reused</c> (409).
/// </summary>
/// <param name="Id">The new bucket's ID, a version 7 UUID generated by the client.</param>
/// <param name="Name">1 to 60 characters, no surrounding white space; unique among the owner's active buckets without regard to case (<c>bucket.name_taken</c>, 422).</param>
/// <param name="Currency">A registered currency code.</param>
/// <param name="Kind">Savings or investment.</param>
/// <param name="Profile">Required for an investment bucket, absent (or <c>null</c>) for a savings bucket.</param>
public sealed record CreateBucketRequest(Guid Id, string Name, Currency Currency, BucketKind Kind, InvestmentProfile? Profile = null);
